comments:
I'm experimenting with
```patch
diff --git a/src/shared/watchdog.c b/src/shared/watchdog.c
index 361d5837dc..9410fddf6b 100644
--- a/src/shared/watchdog.c
+++ b/src/shared/watchdog.c
@@ -32,12 +32,15 @@ static int update_timeout(void) {
                 if (ioctl(watchdog_fd, WDIOC_SETOPTIONS, &flags) < 0)
                         return log_warning_errno(errno, "Failed to disable hardware watchdog: %m");
         } else {
-                int sec, flags;
+                int sec, current_timeout, flags;
                 usec_t t;
 
+                if (ioctl(watchdog_fd, WDIOC_GETTIMEOUT, &current_timeout) < 0)
+                        current_timeout = -1;
+
                 t = DIV_ROUND_UP(watchdog_timeout, USEC_PER_SEC);
                 sec = (int) t >= INT_MAX ? INT_MAX : t; /* Saturate */
-                if (ioctl(watchdog_fd, WDIOC_SETTIMEOUT, &sec) < 0)
+                if (sec != current_timeout && ioctl(watchdog_fd, WDIOC_SETTIMEOUT, &sec) < 0)
                         return log_warning_errno(errno, "Failed to set timeout to %is: %m", sec);
 
                 log_info("Set hardware watchdog to %s.", FORMAT_TIMESPAN(sec * USEC_PER_SEC, 0));
```

That seems to work as desired so far. Didn't think about Reboot/Shutdown/Kexec settings yet. Conceptually, they should also continue to fail if the user configured a deviating timeout from the one the watchdog is tuned to.

